// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        address originalCeo = c.ceoAddress();
        // Try to call DrugDealer with an arbitrary caller
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("DrugDealer()"));
        // The rule: If caller is the original CEO, the call should succeed and ceoAddress should be updated to caller.
        // If caller is not the original CEO, the call should revert and ceoAddress should remain unchanged.
        if (caller == originalCeo) {
            assertTrue(success, "Call by CEO should succeed");
            assertTrue(c.ceoAddress() == caller, "ceoAddress should equal caller");
        } else {
            assertTrue(!success, "Call by non-CEO should revert");
            assertTrue(c.ceoAddress() == originalCeo, "ceoAddress should remain unchanged");
        }
    }
}

